import { Product } from './Product';

export class Catalog {
  private products: Map<string, Product> = new Map();
  private stock: Map<string, number> = new Map();
  private reserved: Map<string, number> = new Map();

  addProduct(product: Product, initialStock: number): void {
    this.products.set(product.id, product);
    this.stock.set(product.id, initialStock);
    this.reserved.set(product.id, 0);
  }

  getProduct(productId: string): Product | undefined {
    return this.products.get(productId);
  }

  getAvailableStock(productId: string): number {
    const total = this.stock.get(productId) ?? 0;
    const reservedAmount = this.reserved.get(productId) ?? 0;
    return total - reservedAmount;
  }

  getTotalStock(productId: string): number {
    return this.stock.get(productId) ?? 0;
  }

  getReservedStock(productId: string): number {
    return this.reserved.get(productId) ?? 0;
  }

  canReserve(productId: string, quantity: number): boolean {
    return this.getAvailableStock(productId) >= quantity;
  }

  reserve(productId: string, quantity: number): void {
    if (!this.canReserve(productId, quantity)) {
      throw new Error(`Insufficient stock for product ${productId}`);
    }
    const currentReserved = this.reserved.get(productId) ?? 0;
    this.reserved.set(productId, currentReserved + quantity);
  }

  release(productId: string, quantity: number): void {
    const currentReserved = this.reserved.get(productId) ?? 0;
    this.reserved.set(productId, Math.max(0, currentReserved - quantity));
  }

  getAllProducts(): Product[] {
    return Array.from(this.products.values());
  }
}

