export type OrderState = 'placed' | 'paid' | 'packed' | 'shipped' | 'delivered';

export interface OrderItem {
  productId: string;
  quantity: number;
}

export interface Order {
  id: string;
  customerId: string;
  items: OrderItem[];
  state: OrderState;
  createdAt: Date;
}

const stateOrder: OrderState[] = ['placed', 'paid', 'packed', 'shipped', 'delivered'];

export function canTransitionTo(currentState: OrderState, newState: OrderState): boolean {
  const currentIndex = stateOrder.indexOf(currentState);
  const newIndex = stateOrder.indexOf(newState);
  return newIndex === currentIndex + 1;
}

export function canCancelOrder(state: OrderState): boolean {
  return state !== 'shipped' && state !== 'delivered';
}

export function createOrder(
  id: string,
  customerId: string,
  items: OrderItem[],
): Order {
  return {
    id,
    customerId,
    items,
    state: 'placed',
    createdAt: new Date(),
  };
}

