import express, { NextFunction, Request, Response } from "express";
import { FulfilmentService, Transition } from "../application/fulfilment-service";
import { DomainError } from "../domain/errors";
import { isOrderState } from "../domain/order";

const STATUS = { validation: 400, not_found: 404, conflict: 409 } as const;

function param(req: Request, name: string): string {
  const value: unknown = req.params[name];
  if (Array.isArray(value)) return String(value[0] ?? "");
  return typeof value === "string" ? value : "";
}

export function createApp(service: FulfilmentService): express.Express {
  const app = express();
  app.use(express.json());

  app.get("/products", (_req, res) => {
    res.json(service.listProducts().map((p) => ({ id: p.id, name: p.name, stock: p.stock })));
  });

  app.get("/products/:id", (req, res) => {
    const p = service.getProduct(param(req, "id"));
    res.json({ id: p.id, name: p.name, stock: p.stock });
  });

  app.post("/products", (req, res) => {
    const body = (req.body ?? {}) as { id?: unknown; name?: unknown; stock?: unknown };
    if (typeof body.id !== "string" || typeof body.name !== "string" || typeof body.stock !== "number") {
      throw new DomainError("validation", "id (string), name (string) and stock (number) are required");
    }
    const p = service.addProduct(body.id, body.name, body.stock);
    res.status(201).json({ id: p.id, name: p.name, stock: p.stock });
  });

  app.post("/orders", (req, res) => {
    const body = (req.body ?? {}) as { customerId?: unknown; items?: unknown };
    if (typeof body.customerId !== "string" || !Array.isArray(body.items)) {
      throw new DomainError("validation", "customerId (string) and items (array) are required");
    }
    const items = (body.items as unknown[]).map((raw) => {
      const item = (raw ?? {}) as { productId?: unknown; quantity?: unknown };
      if (typeof item.productId !== "string" || typeof item.quantity !== "number") {
        throw new DomainError("validation", "each item needs productId (string) and quantity (number)");
      }
      return { productId: item.productId, quantity: item.quantity };
    });
    res.status(201).json(service.placeOrder({ customerId: body.customerId, items }));
  });

  app.get("/orders", (req, res) => {
    const state: unknown = req.query.state;
    if (state === undefined) {
      res.json(service.listOrders());
      return;
    }
    if (typeof state !== "string" || !isOrderState(state)) {
      throw new DomainError("validation", "Unknown order state");
    }
    res.json(service.listOrders(state));
  });

  app.get("/orders/:id", (req, res) => {
    res.json(service.getOrder(param(req, "id")));
  });

  const transitions: Transition[] = ["pay", "pack", "ship", "deliver"];
  for (const t of transitions) {
    app.post(`/orders/:id/${t}`, (req, res) => {
      res.json(service.transition(param(req, "id"), t));
    });
  }

  app.post("/orders/:id/cancel", (req, res) => {
    res.json(service.cancelOrder(param(req, "id")));
  });

  app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    if (err instanceof DomainError) {
      res.status(STATUS[err.kind]).json({ error: err.message });
      return;
    }
    if (err instanceof SyntaxError) {
      res.status(400).json({ error: "Malformed JSON body" });
      return;
    }
    res.status(500).json({ error: "Internal server error" });
  });

  return app;
}

