import { randomUUID } from "node:crypto";
import { NotFoundError } from "../domain/errors";
import { Order } from "../domain/order";
import { OrderStatus } from "../domain/order-status";
import { OrderRepository, ProductRepository } from "../domain/repositories";
import { StockReservationService } from "../domain/stock-reservation-service";
import { OrderDto, PlaceOrderInput, toOrderDto } from "./dtos";

export class OrderService {
  private readonly stock: StockReservationService;

  public constructor(private readonly orders: OrderRepository, products: ProductRepository) {
    this.stock = new StockReservationService(products);
  }

  public place(input: PlaceOrderInput): OrderDto {
    const order = new Order(randomUUID(), input.customerId, input.lines);
    this.stock.reserve(order.lines);
    this.orders.save(order);
    return toOrderDto(order);
  }

  public advance(id: string, status: OrderStatus): OrderDto {
    const order = this.requireOrder(id);
    order.advance(status);
    this.orders.save(order);
    return toOrderDto(order);
  }

  public cancel(id: string): OrderDto {
    const order = this.requireOrder(id);
    order.cancel();
    this.stock.release(order.lines);
    this.orders.save(order);
    return toOrderDto(order);
  }

  public listByStatus(status: OrderStatus): readonly OrderDto[] {
    return this.orders.findByStatus(status).map(toOrderDto);
  }

  private requireOrder(id: string): Order {
    const order = this.orders.findById(id);
    if (!order) throw new NotFoundError(`Order ${id} was not found`);
    return order;
  }
}

