import { ProjectRepository, TaskRepository, UserRepository } from "../domain/Repositories";
import { Task } from "../domain/Task";
import { TaskStatus } from "../domain/TaskStatus";
import { User } from "../domain/User";

export class InMemoryUserRepository implements UserRepository {
  private readonly records = new Map<string, User>();

  public save(user: User): void { this.records.set(user.id, user); }
  public findById(id: string): User | undefined { return this.records.get(id); }
}

export class InMemoryProjectRepository implements ProjectRepository {
  private readonly records = new Map<string, Project>();

  public save(project: Project): void { this.records.set(project.id, project); }
  public findById(id: string): Project | undefined { return this.records.get(id); }
}

export class InMemoryTaskRepository implements TaskRepository {
  private readonly records = new Map<string, Task>();

  public save(task: Task): void { this.records.set(task.id, task); }
  public findById(id: string): Task | undefined { return this.records.get(id); }

  public findByProject(projectId: string, status?: TaskStatus, assigneeId?: string): Task[] {
    return [...this.records.values()].filter((task) =>
      task.projectId === projectId &&
      (!status || task.status === status) &&
      (!assigneeId || task.assigneeId === assigneeId),
    );
  }
}

