    public readonly id: string,
    public readonly projectId: string,
    public readonly title: string,
    public readonly description: string,
    public readonly dueDate: string | undefined,
    public readonly assigneeId: string | undefined,
    status: TaskStatus = "todo",
  ) {
    if (!id.trim() || !projectId.trim() || !title.trim()) {
      throw new DomainError("Task id, project id and title are required");
    }
    if (dueDate !== undefined && Number.isNaN(Date.parse(dueDate))) {
      throw new DomainError("Due date must be a valid date");
    }
    this.status = status;
  }

